const { withAppBuildGradle, withAndroidManifest } = require('expo/config-plugins');

/**
 * Google Play compliance tweaks for the generated Android project (android/ is regenerated by
 * `expo prebuild`, so these must live in a config plugin):
 *
 * 1. R8: use `proguard-android-optimize.txt` instead of `proguard-android.txt`. The latter contains
 *    `-dontoptimize`, which keeps Play's "DEX code optimisation" score low. Minify/shrink are
 *    switched on for release only via expo-build-properties in app.json.
 * 2. Large screens: replace the hard `portrait` lock with `sensorPortrait` (still portrait, but
 *    either way up) and make sure the activity is never marked non-resizable.
 */
function withOptimizedProguard(config) {
  return withAppBuildGradle(config, (c) => {
    c.modResults.contents = c.modResults.contents.replace(
      /getDefaultProguardFile\(["']proguard-android\.txt["']\)/g,
      'getDefaultProguardFile("proguard-android-optimize.txt")'
    );
    return c;
  });
}

function withLargeScreenSupport(config) {
  return withAndroidManifest(config, (c) => {
    for (const activity of c.modResults.manifest.application?.[0]?.activity ?? []) {
      const attrs = activity.$;
      if (attrs['android:name'] !== '.MainActivity') continue;
      if (attrs['android:screenOrientation'] === 'portrait') attrs['android:screenOrientation'] = 'sensorPortrait';
      delete attrs['android:resizeableActivity'];
    }
    return c;
  });
}

module.exports = function withPlayStoreCompliance(config) {
  return withLargeScreenSupport(withOptimizedProguard(config));
};
